func NewID(existing map[string]bool) (string, error) {
	for i := 0; i < 64; i++ {
		b := make([]byte, 3)
		if _, err := rand.Read(b); err != nil {
			return "", err
		}
		id := "t-" + strings.ToLower(base32.StdEncoding.WithPadding(base32.NoPadding).EncodeToString(b))[:4]
		if !existing[id] {
			return id, nil
		}
	}
	return "", errors.New("id space exhausted")
}
